{
  "name": "Nada Concreto",
  "description": "Aplicativo para cálculo de dosagem de concreto baseado no método da UFRN/Ben-Hur, com correções de umidade e cálculo de traço em volume."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum CementClass {
  CP_25 = '25',
  CP_32 = '32',
  CP_40 = '40'
}

export enum ExposureCondition {
  COMUM = 'Comum',
  AMBIENTE_AGRESSIVO = 'Ambiente Agressivo'
}

export enum StructureType {
  DELGADA = 'Delgada',
  COMUM = 'Comum' // Used for both structure type and exposure condition context
}

export enum StandardDeviationControl {
  RIGOROSO = 4.0,
  RAZOAVEL = 5.5,
  REGULAR = 7.0
}

export interface DosageInputs {
  // Project Data
  volumeTotal: number; // m3
  fck: number; // MPa
  sdControl: StandardDeviationControl;
  slump: number; // mm

  // Cement Data
  cementClass: CementClass;
  cementSpecificMass: number; // kg/l (approx 3.1)
  cementUnitMass: number; // kg/l for volume conversion

  // Aggregate Data
  dmc: number; // Maximum diameter (mm)

  // Sand (Miúdo)
  sandSpecificMass: number; // kg/l
  sandUnitMass: number; // kg/l
  sandMoisture: number; // %
  sandSwell?: number; // inchamento (optional, simpler version ignores or assumes 1.0 for mass, needed for detailed volume pad)

  // Gravel (Graúdo)
  gravelSpecificMass: number; // kg/l
  gravelUnitMass: number; // kg/l

  // Algorithm Parameters (The 3 criteria)
  // Default values: as=50%, am=40%, ar=60%
  alphaS: number; // Teor de argamassa seca (%)
  alphaM: number; // Relação agregado miúdo/total (%)
  alphaR: number; // Teor real de argamassa (%)

  // Durability
  exposure: ExposureCondition;
  structureType: StructureType;
}

export interface DosageResults {
  fc28: number;
  waterConsumption: number; // Liters
  waterCementRatio: number; // x
  cementContent: number; // kg

  // Raw Aggregates (Dry)
  totalAggregateMass: number; // M
  sandMassDry: number; // M1
  gravelMassDry: number; // M2

  // Corrected Aggregates (Specific Mass Correction)
  sandMassDryCorrected: number; // M1'
  gravelMassDryCorrected: number; // M2'

  // Moisture Corrected (Wet)
  sandMassWet: number; // Mh1'
  waterCorrected: number; // a'

  // Results per m3
  perM3: {
    cement: number;
    sandWet: number;
    gravel: number;
    water: number;
  };

  // Results for Total Volume
  total: {
    cement: number;
    sandWet: number;
    gravel: number;
    water: number;
  };

  // Volume Trace (Unitary) 1 : n1 : n2 : na
  traceRatio: {
    cement: number;
    sand: number;
    gravel: number;
    water: number;
  };

  // Sack Trace (per 50kg sack)
  sackTrace: {
    cementSacks: number; // For total volume
    sandVolumePerSack: number; // Liters
    gravelVolumePerSack: number; // Liters
    waterVolumePerSack: number; // Liters
  };
}

import { CementClass, StructureType, ExposureCondition } from './types';

// Page 1: Tabela 2 - Quantidade de água
// Rows: Slump (mm), Cols: Dmax (mm) -> 9.5, 19, 25, 38
// We will implement a helper to find the closest match or interpolate if needed, 
// but strictly following the PDF, we assume discrete steps.
export const WATER_TABLE = [
  { slump: 10, dmax: { 9.5: 183, 19: 162, 25: 154, 38: 143 } },
  { slump: 20, dmax: { 9.5: 196, 19: 173, 25: 165, 38: 153 } },
  { slump: 30, dmax: { 9.5: 204, 19: 180, 25: 172, 38: 159 } },
  { slump: 40, dmax: { 9.5: 210, 19: 186, 25: 177, 38: 164 } },
  { slump: 50, dmax: { 9.5: 215, 19: 190, 25: 181, 38: 167 } },
  { slump: 60, dmax: { 9.5: 219, 19: 193, 25: 184, 171: 171 } }, // Note: 171 key logic fix in usage
  { slump: 80, dmax: { 9.5: 225, 19: 199, 25: 189, 38: 176 } },
  { slump: 100, dmax: { 9.5: 230, 19: 203, 25: 194, 38: 180 } },
  { slump: 120, dmax: { 9.5: 235, 19: 207, 25: 197, 38: 183 } },
  { slump: 150, dmax: { 9.5: 240, 19: 212, 25: 202, 38: 187 } },
  { slump: 180, dmax: { 9.5: 244, 19: 216, 25: 205, 38: 190 } },
];

// Page 1: Tabela - Constantes do cimento (A' e B')
export const CEMENT_CONSTANTS: Record<CementClass, { A: number; B: number }> = {
  [CementClass.CP_25]: { A: 17, B: 9 },
  [CementClass.CP_32]: { A: 21, B: 11 },
  [CementClass.CP_40]: { A: 26, B: 14 },
};

// Page 1: Tabela - Critério de Durabilidade (Max a/c)
// Key: StructureType + Exposure
export const DURABILITY_TABLE = {
  [StructureType.DELGADA]: {
    [ExposureCondition.COMUM]: 0.45,
    [ExposureCondition.AMBIENTE_AGRESSIVO]: 0.40,
  },
  [StructureType.COMUM]: {
    [ExposureCondition.COMUM]: 0.50,
    [ExposureCondition.AMBIENTE_AGRESSIVO]: 0.45,
  },
};

// Defaults
export const DEFAULT_CEMENT_SPECIFIC_MASS = 3.1;
export const CEMENT_SACK_VOLUME_LITERS = 35; // approx volume of 50kg sack
export const CEMENT_SACK_WEIGHT_KG = 50;

import { DosageInputs, DosageResults, CEMENT_CONSTANTS, DURABILITY_TABLE, WATER_TABLE, CEMENT_SACK_VOLUME_LITERS, CEMENT_SACK_WEIGHT_KG } from '../types';
import { CementClass } from '../constants'; // Ensure correct import

// Helper to get water content from table
const getWaterContent = (slump: number, dmax: number): number => {
  // Find closest slump row
  const row = WATER_TABLE.reduce((prev, curr) => {
    return (Math.abs(curr.slump - slump) < Math.abs(prev.slump - slump) ? curr : prev);
  });

  // Find closest dmax column
  const dmaxKeys = [9.5, 19, 25, 38];
  const closestDmax = dmaxKeys.reduce((prev, curr) => {
    return (Math.abs(curr - dmax) < Math.abs(prev - dmax) ? curr : prev);
  });

  // @ts-ignore - access safe due to structure
  return row.dmax[closestDmax] || 200; // Fallback
};

export const calculateDosage = (inputs: DosageInputs): DosageResults => {
  // 1. Resistência fc28
  const fc28 = inputs.fck + 1.65 * inputs.sdControl;

  // 2. Quantidade de Água (a)
  const waterConsumption = getWaterContent(inputs.slump, inputs.dmc);

  // 3. Relação Água/Cimento (x)
  // a) Resistência
  const { A, B } = CEMENT_CONSTANTS[inputs.cementClass];
  const acResistence = A / (fc28 + B);

  // b) Durabilidade
  const acDurability = DURABILITY_TABLE[inputs.structureType][inputs.exposure];

  // Menor valor prevalece
  const waterCementRatio = Math.min(acResistence, acDurability);

  // 4. Teor de Cimento (c)
  const cementContent = waterConsumption / waterCementRatio;

  // 5. Teor de Agregado Total (M)
  // M = (1000 - c/gc - a) * gm
  // gm = média das massas específicas
  const gm = (inputs.sandSpecificMass + inputs.gravelSpecificMass) / 2;
  const totalAggregateMass = (1000 - (cementContent / inputs.cementSpecificMass) - waterConsumption) * gm;

  // 6. Proporção Areia/Brita (Mediana de 3 métodos)

  // Método A: Teor de argamassa seca (as)
  // M1 = as * (c + M) - c
  const asDecimal = inputs.alphaS / 100;
  const m1_methodA = (asDecimal * (cementContent + totalAggregateMass)) - cementContent;
  const sandRatioA = m1_methodA / totalAggregateMass;

  // Método B: Relação miúdo/total (am)
  // M1 = am * M
  const amDecimal = inputs.alphaM / 100;
  const m1_methodB = amDecimal * totalAggregateMass;
  const sandRatioB = m1_methodB / totalAggregateMass;

  // Método C: Teor real de argamassa (ar)
  // M2 = (1 - ar) * g_concreto
  // g_concreto estimate? PDF says: M2 = (1-ar) * g_concreto
  // We need g_concreto. Usually g_concreto = c + M + a (approx 2300-2400) if we assume volume=1m3
  // Let's calculate theoretical g_concreto first based on the mix so far.
  const g_concreto = cementContent + totalAggregateMass + waterConsumption; 
  const arDecimal = inputs.alphaR / 100;
  const m2_methodC = (1 - arDecimal) * g_concreto;
  const m1_methodC = totalAggregateMass - m2_methodC;
  const sandRatioC = m1_methodC / totalAggregateMass;

  // Calculate Median Ratio
  const ratios = [sandRatioA, sandRatioB, sandRatioC].sort((a, b) => a - b);
  const medianRatio = ratios[1];

  // Final Raw Masses
  const sandMassDry = totalAggregateMass * medianRatio; // M1
  const gravelMassDry = totalAggregateMass * (1 - medianRatio); // M2

  // 7. Correção das massas (Volume absoluto)
  // M1' = M1 * g1 / gm
  // M2' = M2 * g2 / gm
  const sandMassDryCorrected = (sandMassDry * inputs.sandSpecificMass) / gm;
  const gravelMassDryCorrected = (gravelMassDry * inputs.gravelSpecificMass) / gm;

  // 8. Correção de Umidade
  // Mh1' = M1' * (1 + h)
  const hDecimal = inputs.sandMoisture / 100;
  const sandMassWet = sandMassDryCorrected * (1 + hDecimal);

  // Correct water: a' = a - (Mh1' - M1')
  // The water carried by sand reduces the added water
  const waterCarriedBySand = sandMassWet - sandMassDryCorrected;
  const waterCorrected = waterConsumption - waterCarriedBySand;

  // 9. & 10. & 11. Results

  // Volume unitário (Traço)
  // v_c = 1
  // v_sand = (sandMassDryCorrected / cementContent) * (dc / d_sand) -- Wait, the PDF Method:
  // PDF 11: vc = c/dc, v1 = Mh1'/d1 ?? No, usually Trace is dry based for specification, but pad tools use wet.
  // PDF Step 10: Ratio by Mass (Dry): 1 : m1 : m2 : x
  // PDF Step 11: Ratio by Volume: 1 : n1 : n2 : na
  // n1 = v1/vc = (Mh1_or_Dry? / d1) / (c / dc)
  // Usually Volume Trace is based on DRY or WET depending on site. 
  // Step 11 Formula: v1 = Mh1' / d1. This implies using the WET sand mass for the volume calculation (common in Brazil site mix).
  // Let's follow PDF: v1 = Mh1'/d1.

  const volCement = cementContent / inputs.cementUnitMass; // Liters (if Mass is kg and UnitMass kg/L)
  const volSand = sandMassWet / inputs.sandUnitMass;
  const volGravel = gravelMassDryCorrected / inputs.gravelUnitMass;
  const volWater = waterCorrected; // Density 1

  // Normalize to Cement = 1
  const traceRatio = {
    cement: 1,
    sand: volSand / volCement,
    gravel: volGravel / volCement,
    water: volWater / volCement // This is effectively liters of water per volume of cement equivalent
  };

  // Sack Trace (50kg)
  // 1 sack = 35 liters (approx) or use mass/unit_mass
  const cementSacksTotal = (inputs.volumeTotal * cementContent) / CEMENT_SACK_WEIGHT_KG;

  // Volume per sack
  const sandVolPerSack = traceRatio.sand * CEMENT_SACK_VOLUME_LITERS; // Using 35L reference for volume ratio
  const gravelVolPerSack = traceRatio.gravel * CEMENT_SACK_VOLUME_LITERS;

  // Water per sack (mass balance approach is better for precision, but volume ratio * 35L is the site method)
  // Actually, Water per sack = (Water Total / Cement Total) * 50kg
  const waterPerSack = (waterCorrected / cementContent) * CEMENT_SACK_WEIGHT_KG;

  return {
    fc28,
    waterConsumption,
    waterCementRatio,
    cementContent,
    totalAggregateMass,
    sandMassDry,
    gravelMassDry,
    sandMassDryCorrected,
    gravelMassDryCorrected,
    sandMassWet,
    waterCorrected,
    perM3: {
      cement: cementContent,
      sandWet: sandMassWet,
      gravel: gravelMassDryCorrected,
      water: waterCorrected
    },
    total: {
      cement: cementContent * inputs.volumeTotal,
      sandWet: sandMassWet * inputs.volumeTotal,
      gravel: gravelMassDryCorrected * inputs.volumeTotal,
      water: waterCorrected * inputs.volumeTotal
    },
    traceRatio,
    sackTrace: {
      cementSacks: cementSacksTotal,
      sandVolumePerSack: sandVolPerSack,
      gravelVolumePerSack: gravelVolPerSack,
      waterVolumePerSack: waterPerSack
    }
  };
};

import React from 'react';
import { Hammer, HardHat } from 'lucide-react';

const Header: React.FC = () => {
  return (
    <header className="bg-slate-900 text-white shadow-lg sticky top-0 z-50">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="bg-yellow-500 p-2 rounded-lg text-slate-900">
            <Hammer size={24} strokeWidth={2.5} />
          </div>
          <div>
            <h1 className="text-2xl font-bold tracking-tight">Nada Concreto</h1>
            <p className="text-xs text-slate-400 font-medium">UFRN • Engenharia Civil</p>
          </div>
        </div>

        <div className="flex items-center gap-4 text-sm text-slate-300">
          <div className="hidden md:flex flex-col items-end">
            <span className="font-semibold text-white">Criado por Ben-Hur</span>
            <span className="text-xs">Procedimento de Dosagem</span>
          </div>
          <HardHat className="text-yellow-500" />
        </div>
      </div>
    </header>
