// Ex: 18.3 -> 18.5; 27.7 -> 28.0
const roundUpToHalf = (num: number): number => {
  return Math.ceil(num * 2) / 2;
};

// Helper: Calculate Padiola Dimensions
// Base Assumption: 35cm x 45cm (Standard Cement Sack Mouth)
