  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*');

      if (error) throw error;

      if (data) {
        // Combina o Admin fixo com os usuários do banco
        const dbUsers = data.map((u: any) => ({
          id: u.id,
          username: u.username,
          password: u.password,
          name: u.name,
          role: u.role as UserRole
        }));
        setUsers([ADMIN_USER, ...dbUsers]);
      }
    } catch (err) {
      console.error('Erro ao buscar usuários do banco de dados:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    try {
      sessionStorage.setItem('benhur_current_user', JSON.stringify(user));
    } catch (e) {
      console.warn("Falha ao salvar sessão", e);
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setShowAdminView(false);
    try {
      sessionStorage.removeItem('benhur_current_user');
    } catch (e) {
      console.warn("Falha ao limpar sessão", e);
    }
  };

  const handleAddUser = async (userData: Omit<User, 'id'>) => {
    const newUser = {
      id: Math.random().toString(36).substr(2, 9),
      ...userData
    };

    try {
      const { error } = await supabase
        .from('users')
        .insert([newUser]);

      if (error) throw error;

      // Atualiza lista local após sucesso no banco
      await fetchUsers();
    } catch (err) {
      alert("Erro ao salvar no banco de dados. Verifique a conexão.");
      console.error(err);
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (id === ADMIN_USER.id) return;

    try {
      const { error } = await supabase
        .from('users')
        .delete()
        .eq('id', id);

      if (error) throw error;

      await fetchUsers();
    } catch (err) {
      alert("Erro ao excluir do banco de dados.");
      console.error(err);
    }
  };

  const handleImportUsers = async (importedUsers: User[]) => {
    // Para importação em massa via código para o banco de dados
    const toImport = importedUsers
      .filter(u => u.id !== ADMIN_USER.id)
      .map(u => ({
        id: u.id,
        username: u.username,
        password: u.password,
        name: u.name,
        role: u.role
      }));

    if (toImport.length === 0) return;

    try {
      const { error } = await supabase
        .from('users')
        .upsert(toImport);

      if (error) throw error;

      await fetchUsers();
    } catch (err) {
      alert("Erro na sincronização em massa com o banco.");
    }
  };

  const handleCalculate = () => {
    try {
      const res = calculateDosage(inputs);
      setResults(res);
      setTimeout(() => {
        document.getElementById('results-section')?.scrollIntoView({ behavior: 'smooth' });
      }, 100);
    } catch (error) {
      alert("Erro no cálculo. Verifique os dados.");
    }
  };

  if (loading && !currentUser) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-100">
        <div className="text-[#1C448E] font-bold animate-pulse">Conectando ao banco de dados...</div>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={users} onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col">
