};

function App() {
  const [users, setUsers] = useState<User[]>([ADMIN_USER]);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(false);
  const [dbSetupRequired, setDbSetupRequired] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    try {
      const session = sessionStorage.getItem('benhur_current_user');
      return session ? JSON.parse(session) : null;
    } catch (e) {
      return null;
    }
  });

  const [showAdminView, setShowAdminView] = useState(false);
  const [results, setResults] = useState<DosageResults | null>(null);

  const [inputs, setInputs] = useState<DosageInputs>({
    volumeTotal: 1,
    fck: 25,
    sdControl: StandardDeviationControl.RAZOAVEL,
    slump: 60,
    cementClass: CementClass.CP_32,
    cementSpecificMass: DEFAULT_CEMENT_SPECIFIC_MASS,
    cementUnitMass: 1.4,
    dmc: 19,
    sandSpecificMass: 2.63,
    sandUnitMass: 1.5,
    sandMoisture: 3.0,
    gravelSpecificMass: 2.65,
    gravelUnitMass: 1.45,
    alphaS: 50,
    alphaM: 40,
    alphaR: 60,
    exposure: ExposureCondition.COMUM,
    structureType: StructureType.COMUM
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*');

      if (error) {
        if (error.code === '42501' || error.message?.includes('denied')) {
          setDbSetupRequired(true);
          throw error;
        }
        throw error;
      }

      if (data) {
        const dbUsers = data.map((u: any) => ({
          id: u.id,
          username: u.username,
          password: u.password,
          name: u.name,
          role: u.role as UserRole
        }));
        setUsers([ADMIN_USER, ...dbUsers]);
        setIsOnline(true);
        setDbSetupRequired(false);
      }
    } catch (err) {
      console.warn('Banco de dados não configurado ou inacessível.');
      setIsOnline(false);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    sessionStorage.setItem('benhur_current_user', JSON.stringify(user));
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setShowAdminView(false);
    sessionStorage.removeItem('benhur_current_user');
  };

  const handleAddUser = async (userData: Omit<User, 'id'>) => {
    const newUser = { id: Math.random().toString(36).substr(2, 9), ...userData };
    try {
      const { error } = await supabase.from('users').insert([newUser]);
      if (error) throw error;
      await fetchUsers();
    } catch (err: any) {
      setUsers(prev => [...prev, newUser as User]);
      alert('Usuário salvo apenas localmente. Verifique as permissões do Supabase.');
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (id === ADMIN_USER.id) return;
    try {
      const { error } = await supabase.from('users').delete().eq('id', id);
      if (error) throw error;
      await fetchUsers();
    } catch (err) {
      setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  const handleImportUsers = async (importedUsers: User[]) => {
    const toImport = importedUsers.filter(u => u.id !== ADMIN_USER.id);
    if (toImport.length === 0) return;
    try {
      await supabase.from('users').upsert(toImport);
      await fetchUsers();
    } catch (err) {
      setUsers(prev => [...prev, ...toImport]);
    }
  };

  const handleCalculate = () => {
    const res = calculateDosage(inputs);
    setResults(res);
    setTimeout(() => {
      document.getElementById('results-section')?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
