          </div>

          <div className="text-center mb-10">
            <h2 className="text-4xl font-black text-[#1C448E] tracking-tighter uppercase italic">
              {showAdminView ? 'Configurações de Acesso' : 'Calculadora de Traço'}
            </h2>
            <div className="h-1.5 w-24 bg-[#0084CA] mx-auto mt-4 rounded-full"></div>
          </div>

          {dbSetupRequired && showAdminView && (
            <div className="mb-8 p-6 bg-red-50 border-2 border-red-200 rounded-xl flex gap-4 items-start animate-pulse">
              <AlertTriangle className="text-red-600 shrink-0" size={32} />
              <div>
                <h4 className="text-red-800 font-black uppercase text-sm">Configuração de Banco Necessária</h4>
