          <p className="text-sm font-light opacity-60">
            Dosagem Racional de Concreto (UFRN) • Ben-Hur Ribeiro
          </p>
          <p className="text-[10px] font-black tracking-[0.4em] opacity-40 uppercase">
            Soli Deo Gloria &copy; 2025
          </p>
        </div>
      </footer>
    </div>
  );
}

