    cementSpecificMass: DEFAULT_CEMENT_SPECIFIC_MASS,
    cementUnitMass: 1.4,
    dmc: 19,
    sandSpecificMass: 2.63,
    sandUnitMass: 1.5,
    sandMoisture: 3.0,
    gravelSpecificMass: 2.65,
    gravelUnitMass: 1.45,
    alphaS: 50,
    alphaM: 40,
    alphaR: 60,
    exposure: ExposureCondition.COMUM,
    structureType: StructureType.COMUM
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('users')
        .select('*');

      if (error) throw error;

      if (data && data.length > 0) {
        const dbUsers = data.map((u: any) => ({
          id: u.id,
          username: u.username,
          password: u.password,
          name: u.name,
          role: u.role as UserRole
        }));
        setUsers([ADMIN_USER, ...dbUsers]);
        setIsOnline(true);
      } else {
        setIsOnline(true); // Conectado, mas tabela vazia
      }
    } catch (err: any) {
      // Ignora silenciosamente o erro de permissão e usa o admin padrão
      setIsOnline(false);
      setUsers([ADMIN_USER]);
